using System.Globalization;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
using DotDeck.App.Infrastructure.Windows;
using DotDeck.Core.Documents;
using DotDeck.Core.Files;
using ICSharpCode.AvalonEdit.Document;
using Microsoft.Web.WebView2.Core;
using Microsoft.Web.WebView2.Wpf;

namespace DotDeck.App.Views.Editor;

/// <summary>
/// Live Markdown preview of a <see cref="TextDocument"/> (DESIGN §3). The page is generated by Core
/// (<see cref="MarkdownPreview"/>), written to DotDeck's private pages folder and shown through a virtual host;
/// images of the document folder are served by DotDeck after <see cref="MarkdownPreview.ResolveContentFile"/>;
/// everything else (network, other hosts, secret files, navigation, new windows, downloads) is blocked.
/// The WebView is created while the view is loaded and disposed when it unloads (tab switch, close).
/// </summary>
public partial class MarkdownPreviewView : UserControl
{
    public static readonly DependencyProperty DocumentProperty = DependencyProperty.Register(
        nameof(Document), typeof(TextDocument), typeof(MarkdownPreviewView), new PropertyMetadata(null, OnSourceChanged));

    public static readonly DependencyProperty FilePathProperty = DependencyProperty.Register(
        nameof(FilePath), typeof(string), typeof(MarkdownPreviewView), new PropertyMetadata(null, OnSourceChanged));

    private static readonly TimeSpan s_renderDelay = TimeSpan.FromMilliseconds(300);

    private readonly DispatcherTimer _renderTimer;
    private readonly string _pageName = $"{Guid.NewGuid():N}.html";
    private WebView2? _web;
    private TextDocument? _subscribed;
    private readonly SemaphoreSlim _writeGate = new(1, 1);
    private string? _contentFolder;
    private int _version;
    private double _restoreScroll;
    private bool _initializing;

    public MarkdownPreviewView()
    {
        InitializeComponent();
        _renderTimer = new DispatcherTimer(s_renderDelay, DispatcherPriority.Background, (_, _) => _ = RenderAsync(), Dispatcher) { IsEnabled = false };
        Loaded += (_, _) => _ = StartAsync();
        Unloaded += (_, _) => Stop();
        IsVisibleChanged += (_, _) =>
        {
            if (IsVisible)
            {
                _ = StartAsync();
            }
        };
    }

    public TextDocument? Document
    {
        get => (TextDocument?)GetValue(DocumentProperty);
        set => SetValue(DocumentProperty, value);
    }

    public string? FilePath
    {
        get => (string?)GetValue(FilePathProperty);
        set => SetValue(FilePathProperty, value);
    }

    private string PagePath => Path.Combine(WebViewEnvironment.PagesFolder, _pageName);

    private static void OnSourceChanged(DependencyObject d, DependencyPropertyChangedEventArgs e) =>
        ((MarkdownPreviewView)d).Subscribe();

    private void Subscribe()
    {
        if (_subscribed is not null)
        {
            _subscribed.TextChanged -= OnTextChanged;
        }

        _subscribed = IsLoaded ? Document : null;
        if (_subscribed is not null)
        {
            _subscribed.TextChanged += OnTextChanged;
        }

        ScheduleRender();
    }

    private void OnTextChanged(object? sender, EventArgs e) => ScheduleRender();

    private void ScheduleRender()
    {
        _renderTimer.Stop();
        if (_web?.CoreWebView2 is not null)
        {
            _renderTimer.Start();
        }
    }

    private async Task StartAsync()
    {
        if (_web is not null || _initializing || !IsLoaded || !IsVisible)
        {
            return;
        }

        if (WebViewEnvironment.RuntimeVersion is null)
        {
            ShowMessage("Microsoft Edge WebView2 런타임이 없어 미리보기를 표시할 수 없습니다. 편집기에서 텍스트로 확인하세요.");
            return;
        }

        _initializing = true;
        var web = new WebView2 { DefaultBackgroundColor = ToDrawingColor("DD.Color.Editor.Background") };
        try
        {
            Host.Children.Add(web);
            await web.EnsureCoreWebView2Async(await WebViewEnvironment.GetAsync());
            if (!IsLoaded)
            {
                Host.Children.Remove(web);
                web.Dispose();
                return;
            }

            Configure(web.CoreWebView2);
            _web = web;
            Message.Visibility = Visibility.Collapsed;
            Subscribe();
            await RenderAsync();
        }
        catch (Exception ex) when (ex is COMException or InvalidOperationException or IOException or UnauthorizedAccessException or WebView2RuntimeNotFoundException)
        {
            Host.Children.Remove(web);
            web.Dispose();
            ShowMessage($"미리보기를 시작하지 못했습니다: {ex.Message}");
        }
        finally
        {
            _initializing = false;
        }
    }

    private void Configure(CoreWebView2 core)
    {
        var settings = core.Settings;
        settings.AreDevToolsEnabled = false;
        settings.AreDefaultContextMenusEnabled = false;
        settings.AreDefaultScriptDialogsEnabled = false;
        settings.AreHostObjectsAllowed = false;
        settings.IsWebMessageEnabled = false;
        settings.IsGeneralAutofillEnabled = false;
        settings.IsPasswordAutosaveEnabled = false;
        settings.IsZoomControlEnabled = false;
        settings.IsPinchZoomEnabled = false;
        settings.IsStatusBarEnabled = false;
        settings.AreBrowserAcceleratorKeysEnabled = false;
        settings.IsSwipeNavigationEnabled = false;

        // Page scripts stay blocked by the page CSP (default-src 'none'); only DotDeck's own ExecuteScriptAsync
        // calls (scroll position) run.
        settings.IsScriptEnabled = true;

        core.SetVirtualHostNameToFolderMapping(MarkdownPreview.PageHost, WebViewEnvironment.PagesFolder, CoreWebView2HostResourceAccessKind.Deny);
        core.AddWebResourceRequestedFilter("*", CoreWebView2WebResourceContext.All);
        core.WebResourceRequested += OnWebResourceRequested;
        core.NavigationStarting += (_, e) =>
        {
            if (!Uri.TryCreate(e.Uri, UriKind.Absolute, out var uri) || !IsOwnPage(uri))
            {
                e.Cancel = true;
            }
        };
        core.FrameNavigationStarting += (_, e) => e.Cancel = true;
        core.NewWindowRequested += (_, e) => e.Handled = true;
        core.DownloadStarting += (_, e) => e.Cancel = true;
        core.PermissionRequested += (_, e) => e.State = CoreWebView2PermissionState.Deny;
        core.NavigationCompleted += (_, _) => _ = RestoreScrollAsync();
    }

    private bool IsOwnPage(Uri uri) =>
        string.Equals(uri.Host, MarkdownPreview.PageHost, StringComparison.OrdinalIgnoreCase)
        && string.Equals(uri.AbsolutePath, "/" + _pageName, StringComparison.OrdinalIgnoreCase);

    // Every request passes here. The own page is left to its (Deny) folder mapping; document images are served
    // by DotDeck itself after MarkdownPreview.ResolveContentFile checks them; everything else gets 403.
    private async void OnWebResourceRequested(object? sender, CoreWebView2WebResourceRequestedEventArgs e)
    {
        if (sender is not CoreWebView2 core || !Uri.TryCreate(e.Request.Uri, UriKind.Absolute, out var uri))
        {
            return;
        }

        if (MarkdownPreview.IsAllowedRequest(uri) && IsOwnPage(uri))
        {
            return;
        }

        var file = MarkdownPreview.ResolveContentFile(PhysicalFileStore.Instance, _contentFolder, uri);
        if (file is null)
        {
            e.Response = core.Environment.CreateWebResourceResponse(null, 403, "Forbidden", string.Empty);
            return;
        }

        using var deferral = e.GetDeferral();
        try
        {
            var bytes = await Task.Run(() => File.ReadAllBytes(file.Path));
            e.Response = MarkdownPreview.LooksLikeImage(bytes, file.ContentType)
                ? core.Environment.CreateWebResourceResponse(
                    new MemoryStream(bytes, writable: false), 200, "OK", $"Content-Type: {file.ContentType}")
                : core.Environment.CreateWebResourceResponse(null, 403, "Forbidden", string.Empty);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or COMException or InvalidOperationException)
        {
            try
            {
                e.Response = core.Environment.CreateWebResourceResponse(null, 404, "Not Found", string.Empty);
            }
            catch (Exception inner) when (inner is COMException or InvalidOperationException)
            {
                // WebView already gone.
            }
        }
    }

    private async Task RenderAsync()
    {
        _renderTimer.Stop();
        if (_web?.CoreWebView2 is not { } core || Document is not { } document)
        {
            return;
        }

        var text = document.Text;
        var path = FilePath ?? string.Empty;
        var theme = CurrentTheme();
        var version = ++_version;
        try
        {
            _contentFolder = Path.GetDirectoryName(path);
            var html = await Task.Run(() => MarkdownPreview.BuildPage(text, theme, Path.GetFileName(path)));
            if (!IsCurrent(version, core))
            {
                return;
            }

            if (double.TryParse(await core.ExecuteScriptAsync("window.scrollY"), NumberStyles.Float, CultureInfo.InvariantCulture, out var y))
            {
                _restoreScroll = y;
            }

            // Writes never overlap; a render that became stale while waiting stops before writing or navigating.
            await _writeGate.WaitAsync();
            try
            {
                if (!IsCurrent(version, core))
                {
                    return;
                }

                await File.WriteAllTextAsync(PagePath, html, new UTF8Encoding(false));
            }
            finally
            {
                _writeGate.Release();
            }

            if (!IsCurrent(version, core))
            {
                return;
            }

            core.Navigate($"https://{MarkdownPreview.PageHost}/{_pageName}?v={version.ToString(CultureInfo.InvariantCulture)}");
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or COMException or InvalidOperationException)
        {
            ShowMessage($"미리보기를 만들지 못했습니다: {ex.Message}");
        }
    }

    private bool IsCurrent(int version, CoreWebView2 core) => version == _version && _web?.CoreWebView2 == core;

    private async Task RestoreScrollAsync()
    {
        if (_web?.CoreWebView2 is { } core && _restoreScroll > 0)
        {
            try
            {
                await core.ExecuteScriptAsync($"window.scrollTo(0,{_restoreScroll.ToString(CultureInfo.InvariantCulture)})");
            }
            catch (Exception ex) when (ex is COMException or InvalidOperationException)
            {
            }
        }
    }

    private void Stop()
    {
        _renderTimer.Stop();
        if (_subscribed is not null)
        {
            _subscribed.TextChanged -= OnTextChanged;
            _subscribed = null;
        }

        if (_web is not null)
        {
            Host.Children.Remove(_web);
            _web.Dispose();
            _web = null;
            _contentFolder = null;
        }

        try
        {
            File.Delete(PagePath);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
        }
    }

    private void ShowMessage(string text)
    {
        Message.Text = text;
        Message.Visibility = Visibility.Visible;
    }

    private MarkdownTheme CurrentTheme() => new(
        Hex("DD.Color.Editor.Background"),
        Hex("DD.Color.Editor.Text"),
        Hex("DD.Color.Text.Secondary"),
        Hex("DD.Color.Border"),
        Hex("DD.Color.Chrome.Background"),
        Hex("DD.Color.Accent.Hover"),
        FontName("DD.Font.Ui"),
        FontName("DD.Font.Editor"));

    private string Hex(string key) =>
        TryFindResource(key) is Color c ? $"#{c.R:X2}{c.G:X2}{c.B:X2}" : "inherit";

    private string FontName(string key) =>
        TryFindResource(key) is FontFamily f ? f.Source : "sans-serif";

    private System.Drawing.Color ToDrawingColor(string key) =>
        TryFindResource(key) is Color c ? System.Drawing.Color.FromArgb(c.A, c.R, c.G, c.B) : System.Drawing.Color.Black; // theme-color-ok: converts a theme resource color for WebView2
}
